  const mt = table('saMods', [{ h: 'Module', k: r => r.m.name, t: 'text', cls: 'wrap' }, { h: 'Status', k: r => pill(r.m.status, r.m.status === 'Active' ? 'ok' : r.m.status === 'Inactive' || r.m.status === 'Under Maintenance' ? 'bad' : 'warn') + (r.m.mods.length ? '' : ' ' + pill('Not connected', '')), t: 'html', x: r => r.m.status }, { h: 'Screens', k: r => r.m.mods.length, t: 'num' }, { h: 'Users active', k: r => r.users, t: 'num' }, { h: 'Report views', k: r => r.views, t: 'num' }, { h: 'Pending approvals', k: r => r.pend, t: 'num', rc: r => r.pend ? 'amber' : '' }], modRows, { compact: true });
  const crit = A.filter(a => /delet|revers|withdraw|remov|closed|Blocked|failed|Failed|override|Reject/i.test(a.action) || a.module === 'Session' && /Failed/.test(a.action)).slice(0, 12);
