async function saReqOk() {
  const err = t => { const e = $('#arErr'); e.textContent = t; e.hidden = false; }; const reason = (v('arR') || '').trim(); if (!reason) return err('Enter the business reason.');
  const acts = [...$('#arP').selectedOptions].map(o => o.value); if (!acts.length) return err('Choose the permission type.'); const from = v('arF'), to = v('arT'); if (to && to < from) return err('The end date is before the start date.');
  const R = Store.clone(Store.get('accessreq')), u = App.user, o = { id: 'AR' + Date.now().toString(36), by: u.id, byName: u.name, role: u.role, mod: v('arM'), acts, branches: [...$('#arB').selectedOptions].map(x => x.value), from, to, reason, manager: v('arMg'), managerOk: false, status: 'Pending', at: nowIso() };
  R.list.push(o); await Store.put('accessreq', R); audit('Access Requests', 'Access request raised', { new: `${(MODULES.find(m => m[0] === o.mod) || [])[1]} · ${acts.join(', ')} · ${from} → ${to || 'open'}`, reason, approval: 'Pending' }); closeModal(); toast('Request submitted.');
}
function saReqDecide(id, kind) {
  const r = Store.get('accessreq').list.find(x => x.id === id); if (!r) return;
  if (kind === 'reject') return askReason('Reject access request', r.byName + ' · ' + (MODULES.find(m => m[0] === r.mod) || [])[1], async rs => { const R = Store.clone(Store.get('accessreq')), x = R.list.find(y => y.id === id); x.status = 'Rejected'; x.decisionNote = rs; x.decidedBy = App.user.name; x.decidedAt = nowIso(); await Store.put('accessreq', R); audit('Access Requests', 'Access request rejected', { old: x.byName, new: x.acts.join(', '), reason: rs, approval: 'Rejected', approver: App.user.name }); toast('Rejected.'); });
  modal((kind === 'modify' ? 'Modify and grant' : 'Approve') + ' · ' + r.byName, `<p class="small">${esc((MODULES.find(m => m[0] === r.mod) || [])[1])} · requested ${esc(r.acts.join(', '))} · ${isoLabel(r.from)} → ${r.to ? isoLabel(r.to) : 'open'}${r.manager && !r.managerOk ? ' · <b>manager approval pending</b>' : ''}</p><div class="form-grid"><label class="fld"><span>Permissions granted</span><select id="agP" multiple size="5">${REQ_PERMS.map(p => `<option${r.acts.includes(p) ? ' selected' : ''}>${p}</option>`).join('')}</select></label><label class="fld"><span>Branches</span><select id="agB" multiple size="5">${DATA.branches.filter(b => !b.closed).map(b => `<option value="${b.id}"${(r.branches || []).includes(b.id) ? ' selected' : ''}>${esc(b.name)}</option>`).join('')}</select></label><label class="fld"><span>From</span><input type="date" id="agF" value="${r.from}"></label><label class="fld"><span>To (temporary access expires automatically)</span><input type="date" id="agT" value="${r.to || ''}"></label></div><label class="fld"><span>Decision note (required)</span><textarea id="agR" rows="2"></textarea></label><p class="err" id="agErr" hidden></p>`,
    `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="saReqGrant" data-k="${id}">Grant access</button>`, true);
}
async function saReqGrant(id) {
  const err = t => { const e = $('#agErr'); e.textContent = t; e.hidden = false; }; const note = (v('agR') || '').trim(); if (!note) return err('Enter the decision note.');
  const acts = [...$('#agP').selectedOptions].map(o => o.value); if (!acts.length) return err('Choose at least one permission.');
  const R = Store.clone(Store.get('accessreq')), r = R.list.find(x => x.id === id), G = Store.clone(Store.get('grants'));
  const g = { id: 'G' + Date.now().toString(36), req: id, user: r.by, mod: r.mod, acts, branches: [...$('#agB').selectedOptions].map(o => o.value), from: v('agF'), to: v('agT'), by: App.user.name, at: nowIso(), status: 'Active' };
  G.list.push(g); r.status = 'Approved'; r.decisionNote = note; r.decidedBy = App.user.name; r.decidedAt = nowIso(); r.grant = g.id;
  await Store.put('grants', G); await Store.put('accessreq', R); MEMO.clear(); audit('Access Requests', 'Access granted', { old: r.byName + ' requested ' + r.acts.join(', '), new: `${(MODULES.find(m => m[0] === r.mod) || [])[1]} · ${acts.join(', ')} · ${g.from} → ${g.to || 'open'}`, reason: note, approval: 'Approved', approver: App.user.name }); closeModal(); toast('Access granted.');
}

/* ---------- 10. Reports ---------- */
PAGES.sa_reports = { title: 'Access & Security Reports', mod: 'sa_reports', render() {
  const U = users(), R = Store.get('roles'), A = Store.list('audit'), ses = Store.get('sessions').list, G = Store.get('grants').list, REQ = Store.get('accessreq').list, days = +(App.ui.saDays || 30);
  const TABS = [['matrix', 'User-wise access matrix'], ['roles', 'Role-wise permission matrix'], ['branch', 'Branch-wise user access'], ['modules', 'Module-wise active users'], ['expired', 'Users with expired access'], ['nologin', `No login for ${days} days`], ['locked', 'Locked and inactive users'], ['dup', 'Duplicate users / IDs'], ['sensitive', 'Sensitive data access'], ['export', 'Export / download activity'], ['pending', 'Pending access requests'], ['deleted', 'Audit and deletion report'], ['security', 'Login attempts and incidents']];
  const tab = TABS.some(([k]) => k === App.ui.saTab) ? App.ui.saTab : 'matrix';
  const tabs = `<div class="tabs">${TABS.map(([k, l]) => `<button class="tab${k === tab ? ' on' : ''}" data-act="ui" data-k="saTab" data-v="${k}">${l}</button>`).join('')}</div>`;
  const perms = u => { const set = new Set(); userRoles(u).forEach(r => Object.entries((R[r] || { perms: {} }).perms).forEach(([m, acts]) => acts.forEach(a => set.add(m + '|' + a)))); activeGrants(u).forEach(g => g.acts.forEach(a => set.add(g.mod + '|' + a))); return set; };
  const modName = m => (MODULES.find(x => x[0] === m) || [])[1] || m;
  let body = '';
  if (tab === 'matrix') body = table('saR', [{ h: 'User', k: u => u.name, t: 'text' }, { h: 'Role(s)', k: u => userRoles(u).join(', '), t: 'text' }, { h: 'Status', k: u => u.status, t: 'text' }, { h: 'Branches in scope', k: u => scopeOf(u).size, t: 'num' }, { h: 'Modules', k: u => [...new Set([...perms(u)].map(x => x.split('|')[0]))].length, t: 'num' }, { h: 'Can approve', k: u => [...perms(u)].filter(x => x.endsWith('|Approve')).map(x => modName(x.split('|')[0])).join(', ') || '—', t: 'text', cls: 'wrap small' }, { h: 'Sensitive data', k: u => SENSITIVE_DATA.filter(c => userRoles(u).some(r => (R[r] || {}).sensitive && R[r].sensitive.includes(c))).join(', ') || '—', t: 'text', cls: 'wrap small' }, { h: 'Temporary grants', k: u => activeGrants(u).length, t: 'num' }], U, { limit: 60 });
  else if (tab === 'roles') body = table('saR', [{ h: 'Role', k: r => r, t: 'text' }, { h: 'Active', k: r => R[r] && R[r].active !== false ? 'Yes' : 'No', t: 'text' }, { h: 'Users', k: r => U.filter(u => userRoles(u).includes(r)).length, t: 'num' }, { h: 'Modules', k: r => Object.keys((R[r] || { perms: {} }).perms).length, t: 'num' }, { h: 'Permissions', k: r => Object.entries((R[r] || { perms: {} }).perms).map(([m, a]) => `${modName(m)}: ${a.join(', ')}`).join(' · '), t: 'text', cls: 'wrap small' }, { h: 'Sensitive data', k: r => ((R[r] || {}).sensitive || []).join(', ') || '—', t: 'text', cls: 'wrap small' }], ROLES.filter(r => R[r]), {});
  else if (tab === 'branch') body = table('saR', [{ h: 'Branch', k: b => b.name, t: 'text', cls: 'wrap' }, { h: 'Region / zone', k: b => `${b.region} / ${b.zone}`, t: 'text' }, { h: 'Users with access', k: b => U.filter(u => scopeOf(u).has(DATA.branches.indexOf(b))).length, t: 'num' }, { h: 'Principal', k: b => (U.find(u => u.role === 'Principal' && u.branch === b.id) || {}).name || '—', t: 'text' }, { h: 'Zonal Director', k: b => zdName(b), t: 'text' }, { h: 'Regional Director', k: b => rdName(b), t: 'text' }, { h: 'Branch-only users', k: b => U.filter(u => u.branch === b.id).map(u => u.name).join(', '), t: 'text', cls: 'wrap small' }], DATA.branches.filter(b => !b.closed), { limit: 80 });
  else if (tab === 'modules') body = table('saR', [{ h: 'Module', k: m => m.name, t: 'text', cls: 'wrap' }, { h: 'Status', k: m => m.status, t: 'text' }, { h: 'Users with access', k: m => U.filter(u => m.mods.some(x => [...perms(u)].some(p => p.startsWith(x + '|')))).length, t: 'num' }, { h: 'Active in last 30 days', k: m => new Set(A.filter(a => m.mods.some(x => (PAGES[x] || {}).title === a.module)).map(a => a.userId)).size, t: 'num' }], Store.get('modules').list, {});
  else if (tab === 'expired') { const M = Store.get('mappings'); const rows = U.map(u => ({ u, ended: M.filter(m => m.user === u.id && m.to && m.to < ACCESS_DATE), active: M.filter(m => m.user === u.id && activeOn(m, ACCESS_DATE)).length, grants: G.filter(g => g.user === u.id && g.status === 'Expired').length })).filter(r => r.ended.length && !r.active || r.grants); body = table('saR', [{ h: 'User', k: r => r.u.name, t: 'text' }, { h: 'Role', k: r => r.u.role, t: 'text' }, { h: 'Status', k: r => r.u.status, t: 'text' }, { h: 'Expired mappings', k: r => r.ended.length, t: 'num' }, { h: 'Last expiry', k: r => r.ended.length ? isoLabel(r.ended.map(m => m.to).sort().at(-1)) : '—', t: 'text' }, { h: 'Expired grants', k: r => r.grants, t: 'num' }], rows, { empty: 'No users with expired access.' }); }
  else if (tab === 'nologin') { const cut = E.ds(E.dn(ACCESS_DATE) - days); body = `<div class="ctrls"><label class="fld"><span>Days</span><select data-act="uiSelN" data-k="saDays">${[7, 15, 30, 60, 90].map(d => `<option value="${d}"${d === days ? ' selected' : ''}>${d}</option>`).join('')}</select></label></div>` + table('saR', [{ h: 'User', k: u => u.name, t: 'text' }, { h: 'Role', k: u => u.role, t: 'text' }, { h: 'Status', k: u => u.status, t: 'text' }, { h: 'Last login', k: u => u.lastLogin ? tsLabel(u.lastLogin) : 'Never', t: 'text', x: u => u.lastLogin || '' }, { h: 'Branch', k: u => u.branch ? brName(u.branch) : '—', t: 'text', cls: 'wrap' }], U.filter(u => !u.lastLogin || u.lastLogin.slice(0, 10) < cut), { empty: 'Everyone has signed in within this period.' }); }
  else if (tab === 'locked') body = table('saR', [{ h: 'User', k: u => u.name, t: 'text' }, { h: 'Role', k: u => u.role, t: 'text' }, { h: 'Status', k: u => pill(u.status, 'bad'), t: 'html', x: u => u.status }, { h: 'Last login', k: u => u.lastLogin ? tsLabel(u.lastLogin) : 'Never', t: 'text' }, { h: 'Latest status change', k: u => (A.find(a => /Lock|Deactivate|Activate|Unlock/.test(a.action) && (a.old || '').includes(u.empId)) || {}).reason || '—', t: 'text', cls: 'wrap small' }], U.filter(u => ['Locked', 'Inactive', 'Resigned', 'Pending Activation'].includes(u.status)), { empty: 'No locked or inactive users.' });
  else if (tab === 'dup') { const by = (k, f) => { const m = {}; U.forEach(u => { const x = (f(u) || '').toLowerCase().trim(); if (x) (m[x] = m[x] || []).push(u); }); return Object.entries(m).filter(([, l]) => l.length > 1).map(([x, l]) => ({ kind: k, value: x, users: l })); }; const rows = [...by('Email', u => u.email), ...by('Mobile', u => u.mobile && u.mobile.replace(/X/g, '') ? u.mobile : ''), ...by('Employee ID', u => u.empId), ...by('Name', u => u.name.replace(' (demo)', ''))]; body = table('saR', [{ h: 'Duplicate', k: r => r.kind, t: 'text' }, { h: 'Value', k: r => r.value, t: 'text' }, { h: 'Users', k: r => r.users.map(u => `${u.name} (${u.empId}, ${u.status})`).join('; '), t: 'text', cls: 'wrap small' }], rows, { empty: 'No duplicate emails, mobiles, employee IDs or names.' }); }
  else if (tab === 'sensitive') body = table('saR', [{ h: 'When', k: a => tsLabel(a.ts), t: 'text', x: a => a.ts }, { h: 'User', k: a => a.user, t: 'text' }, { h: 'Role', k: a => a.role, t: 'text' }, { h: 'What', k: a => `${a.module} · ${a.action}`, t: 'text', cls: 'wrap' }, { h: 'Detail', k: a => a.new, t: 'text', cls: 'wrap small' }, { h: 'IP', k: a => a.ip || '—', t: 'text' }], A.filter(a => /Student Corner|Audit|Approvals|Payments|SRF · |salary|bank|concession|Email Reports/i.test(a.module + ' ' + a.action)), { limit: 50, empty: 'No sensitive data access recorded.' });
  else if (tab === 'export') body = table('saR', [{ h: 'When', k: a => tsLabel(a.ts), t: 'text', x: a => a.ts }, { h: 'User', k: a => a.user, t: 'text' }, { h: 'Role', k: a => a.role, t: 'text' }, { h: 'Report', k: a => a.module, t: 'text', cls: 'wrap' }, { h: 'Format', k: a => a.new, t: 'text', cls: 'wrap small' }, { h: 'IP', k: a => a.ip || '—', t: 'text' }], A.filter(a => /export|download|Excel|PDF|CSV/i.test(a.action + ' ' + a.new)), { limit: 50, empty: 'No exports or downloads yet.' });
  else if (tab === 'pending') body = table('saR', [{ h: 'Raised', k: r => tsLabel(r.at), t: 'text', x: r => r.at }, { h: 'User', k: r => r.byName, t: 'text' }, { h: 'Module', k: r => modName(r.mod), t: 'text', cls: 'wrap' }, { h: 'Permission', k: r => r.acts.join(', '), t: 'text' }, { h: 'Duration', k: r => `${isoLabel(r.from)} → ${r.to ? isoLabel(r.to) : 'open'}`, t: 'text' }, { h: 'Manager approval', k: r => r.managerOk ? 'Yes' : 'Pending', t: 'text' }, { h: 'Waiting', k: r => Math.round((Date.now() - Date.parse(r.at)) / 864e5) + ' days', t: 'text' }], REQ.filter(r => r.status === 'Pending'), { empty: 'No pending access requests.' });
  else if (tab === 'deleted') body = table('saR', [{ h: 'When', k: a => tsLabel(a.ts), t: 'text', x: a => a.ts }, { h: 'User', k: a => a.user, t: 'text' }, { h: 'Module', k: a => a.module, t: 'text' }, { h: 'Action', k: a => a.action, t: 'text' }, { h: 'Old value', k: a => a.old, t: 'text', cls: 'wrap small' }, { h: 'New value', k: a => a.new, t: 'text', cls: 'wrap small' }, { h: 'Reason', k: a => a.reason, t: 'text', cls: 'wrap small' }, { h: 'Approver', k: a => a.approver || '—', t: 'text' }, { h: 'IP / device', k: a => `${a.ip || '—'} · ${a.device || ''}`, t: 'text', cls: 'wrap small' }], A.filter(a => /delet|revers|withdraw|remov|closed|cancel/i.test(a.action)), { limit: 60, empty: 'No deletions, reversals or withdrawals recorded.' });
  else body = table('saR', [{ h: 'When', k: s => tsLabel(s.at), t: 'text', x: s => s.at }, { h: 'User', k: s => s.user, t: 'text' }, { h: 'Role', k: s => s.role, t: 'text' }, { h: 'Event', k: s => s.kind === 'Failed login' ? pill('Failed login', 'bad') : s.kind, t: 'html', x: s => s.kind }, { h: 'IP', k: s => s.ip, t: 'text' }, { h: 'Device', k: s => s.device, t: 'text', cls: 'wrap small' }], ses.concat(A.filter(a => a.action === 'Blocked action').map(a => ({ at: a.ts, user: a.user, role: a.role, kind: 'Blocked: ' + a.new, ip: a.ip, device: a.device }))).sort((a, b) => b.at.localeCompare(a.at)), { limit: 60, empty: 'No login attempts or incidents recorded.' });
  return `<div class="note">All reports are searchable with the table sort and downloadable. The audit trail is append-only: no user, including System Admin and Super Admin, can delete audit entries.</div>` + card(TABS.find(([k]) => k === tab)[1], tabs + body, { right: exportBtns('saR', 'sa_reports', { label: false }) });
} };

/* ---------- actions ---------- */
const SA_ACT = {
  saModEdit: t => saModForm(t.dataset.k), saModOk: t => saModOk(t.dataset.k),
  saSens: t => { const role = t.dataset.k, cat = t.dataset.v; askReason((t.checked ? 'Allow' : 'Remove') + ' sensitive data', `${role} · ${cat}`, async r => { const R = Store.clone(Store.get('roles')); R[role].sensitive = R[role].sensitive || []; if (t.checked) { if (!R[role].sensitive.includes(cat)) R[role].sensitive.push(cat); } else R[role].sensitive = R[role].sensitive.filter(x => x !== cat); await Store.put('roles', R); audit('Access & Sensitive Data', 'Sensitive data access changed', { old: role, new: `${cat}: ${t.checked ? 'allowed' : 'removed'}`, reason: r, approval: '—' }); toast('Updated.'); }, ''); setTimeout(rerender, 50); },
  saRuleEdit: t => saRuleForm(t.dataset.k), saRuleOk: t => saRuleOk(t.dataset.k),
  saRuleDel: t => askReason('Remove data access rule', '', async r => { const R = Store.clone(Store.get('datarules')); R.list = R.list.filter(x => x.id !== t.dataset.k); await Store.put('datarules', R); saApplySrfWindows(); MEMO.clear(); audit('Data Access Rules', 'Rule removed', { old: t.dataset.k, reason: r, approval: '—' }); toast('Rule removed.'); }),
  saWfEdit: t => saWfForm(t.dataset.k), saWfOk: t => saWfOk(t.dataset.k),
  saWfLevel: t => { const box = $('#wfLv'); if (!box) return; if (t.dataset.v === '-1') { if (box.children.length > 1) box.lastElementChild.remove(); return; } const n = box.children.length; const d = document.createElement('div'); d.className = 'form-grid'; d.innerHTML = `<label class="fld"><span>Level ${n + 1} roles</span><select class="wfR" multiple size="4">${ROLES.map(r => `<option>${r}</option>`).join('')}</select></label><label class="fld"><span>Applies above amount (₹)</span><input class="wfA" type="number" min="0" value="0"></label><label class="fld"><span>Level type</span><select class="wfK"><option value="">Approve</option><option value="Recommend">Recommend</option><option value="Verify">Verify</option></select></label>`; box.appendChild(d); },
  saReqNew: () => saReqForm(), saReqOk: () => saReqOk(), saReqDecide: t => saReqDecide(t.dataset.k, t.dataset.v), saReqGrant: t => saReqGrant(t.dataset.k),
  saReqMgr: t => askReason('Approve as reporting manager', '', async r => { const R = Store.clone(Store.get('accessreq')), x = R.list.find(y => y.id === t.dataset.k); x.managerOk = true; x.managerNote = r; await Store.put('accessreq', R); audit('Access Requests', 'Manager approval', { new: x.byName + ' · ' + x.acts.join(', '), reason: r, approval: 'Manager approved', approver: App.user.name }); toast('Approved as manager.'); }),
  saGrantRevoke: t => askReason('Revoke temporary access', '', async r => { const G = Store.clone(Store.get('grants')), g = G.list.find(x => x.id === t.dataset.k); g.status = 'Revoked'; g.revokedBy = App.user.name; g.revokedAt = nowIso(); await Store.put('grants', G); MEMO.clear(); audit('Access Requests', 'Temporary access revoked', { old: (userById(g.user) || {}).name, new: g.acts.join(', '), reason: r, approval: '—' }); toast('Access revoked.'); }),
  saFailDemo: () => { const u = users().find(x => x.role === 'Principal'); saSession('Failed login', u); audit('Session', 'Failed login attempt', { new: u.name + ' · wrong password (demo)', approval: '—' }); toast('Failed attempt recorded.'); }
};
